const http=require('http')
const fs=require('fs')
const port=3100;

const server=http.createServer((req,res)=>{
    if(req.method=='POST'){
        let body='';
        req.on('data',(chunk)=>{
            body+=chunk
        })
        req.on("end",()=>{
            fs.writeFile("./sample.js",(body),()=>{
                res.writeHead(200,{'content-type':'application/json'})
                res.write(body);
                res.end();
            })
          
        })
    }
    else{
        res.write("Invalid method")
        res.end()
    }
})
server.listen(port,()=>{
    console.log(`Server is running at ${port}`)
})